71| export function parseFidelityVerdict(stdout: string | null, exitCode: number | null): FidelityVerdict {
72|   if (exitCode !== 0) return "not-evaluated";
73|   const text = (stdout ?? "").trim();
74|   if (text === "faithful" || text === "vacuous") return text;
75|   const candidates = [text, ...text.split(/\r?\n/).map((s) => s.trim()).filter(Boolean).reverse()];
76|   for (const cand of candidates) {
77|     try {
78|       const obj = JSON.parse(cand);
79|       if (obj && typeof obj === "object" && (obj.verdict === "faithful" || obj.verdict === "vacuous")) {
80|         return obj.verdict as FidelityVerdict;
81|       }
82|     } catch {
83|       /* non-JSON line, keep scanning upward */
84|     }
85|   }
86|   return "not-evaluated";
87| }

1142| export function parseSemanticSufficiencyVerdict(stdout: string | null, exitCode: number | null): SufficiencyVerdict {
1143|   if (exitCode !== 0) return "not-evaluated";
1144|   const text = (stdout ?? "").trim();
1145|   // 纯 token（测试缝 / 极简输出）也认。
1146|   if (text === "covered" || text === "insufficient") return text;
1147|   // JSON 形态：{"verdict":"covered"} / {"verdict":"insufficient"}（claude -p 可能带解释性前文，
1148|   // 从末行向上找第一个可解析的 JSON 对象）。⛔ 找不到 ⇒ not-evaluated，绝不默认 covered。
1149|   const candidates = [text, ...text.split(/\r?\n/).map((s) => s.trim()).filter(Boolean).reverse()];
1150|   for (const cand of candidates) {
1151|     try {
1152|       const obj = JSON.parse(cand);
1153|       if (obj && typeof obj === "object" && (obj.verdict === "covered" || obj.verdict === "insufficient")) {
1154|         return obj.verdict as SufficiencyVerdict;
1155|       }
1156|     } catch {
1157|       /* 非 JSON 行，继续向上找 */
1158|     }
1159|   }
1160|   return "not-evaluated";
1161| }
